// Portal adapter must be constructed from observed real links, never guessed IDs.
export function schoolBatch(links,{read,delay=()=>new Promise(r=>setTimeout(r,2000))}={}) {
 if(!Array.isArray(links)||links.length>100||typeof read!=='function')throw Error('Invalid batch');
 const seen=new Map();for(const item of links){const u=new URL(item.url);if(u.protocol!=='https:'||u.username||u.password||u.hash||[...u.searchParams.keys()].some(k=>/token|session|auth|password|secret|key/i.test(k))||!/^\d{1,10}$/.test(item.schoolId))throw Error('Invalid observed link');if(seen.has(item.schoolId)&&seen.get(item.schoolId)!==item.url)throw Error('Conflicting school ID');seen.set(item.schoolId,item.url);}
 if(new Set([...seen.values()].map(u=>new URL(u).origin)).size>1)throw Error('Mixed portal origins');
 const queue=[...seen].map(([schoolId,url])=>({schoolId,url}));let paused=true,running=false,index=0;const results=[];
 return {pause(){paused=true},snapshot(){return {paused,running,next:index,total:queue.length,results:structuredClone(results)}},async resume(){if(running)return;paused=false;running=true;try{while(!paused&&index<queue.length){const item=queue[index];try{const value=await read(item);if(!value||value.schoolId!==item.schoolId||typeof value.jd!=='string'||!value.jd.trim())throw Error('Detail identity or text missing');results.push({...item,status:'done',title:value.title||'',company:value.company||'',jd:value.jd,duration:value.duration||'',applicationInstructions:value.applicationInstructions||'',capturedAt:new Date().toISOString()});index++;}catch{results.push({...item,status:'blocked',reason:'详情读取未确认；请检查登录、访问限制或页面结构'});paused=true;break;}if(index<queue.length&&!paused)await delay();}}finally{running=false;if(index===queue.length)paused=true;}}};
}
